//==========================================
// CART MODULE
// A shopping cart is a singly linked list of game ids.
// It only lives during the login session (it is not saved to a file),
// like a real store cart that you fill before checkout.
//==========================================

struct CartNode {
    int gameId = 0;
    CartNode* next = nullptr;
};

struct Cart {
    CartNode* head = nullptr;
    int count = 0;
};

//--- inCart ---------------------------------------------------------------------------------------
// What    : Searches the cart list for a game id.
// Returns : true when the game is in the cart
// Used by : addToCart, printGameRow (store.h)
//--------------------------------------------------------------------------------------------------
bool inCart(const Cart& cart, int gameId) {
    for (CartNode* cur = cart.head; cur != nullptr; cur = cur->next) {
        if (cur->gameId == gameId) return true;
    }
    return false;
}

// returns false when the game is already in the cart
//--- addToCart ------------------------------------------------------------------------------------
// What    : Appends a game id at the end of the cart list.
// Returns : false when the game is already in the cart
// Used by : doAddToCart (store.h), doBundle (screens.h), doCart (store.h), doWishlist (store.h)
//--------------------------------------------------------------------------------------------------
bool addToCart(Cart& cart, int gameId) {
    if (inCart(cart, gameId)) return false;
    CartNode* node = new CartNode();
    node->gameId = gameId;
    if (cart.head == nullptr) {
        cart.head = node;
    } else {
        CartNode* cur = cart.head;
        while (cur->next != nullptr) cur = cur->next;
        cur->next = node;
    }
    cart.count++;
    return true;
}

//--- removeFromCart -------------------------------------------------------------------------------
// What    : Unlinks one game from the cart and frees the node.
// Returns : false when the game was not in the cart
// Used by : doCart (store.h)
//--------------------------------------------------------------------------------------------------
bool removeFromCart(Cart& cart, int gameId) {
    CartNode* prev = nullptr;
    for (CartNode* cur = cart.head; cur != nullptr; prev = cur, cur = cur->next) {
        if (cur->gameId != gameId) continue;
        if (prev == nullptr) cart.head = cur->next;
        else prev->next = cur->next;
        delete cur;
        cart.count--;
        return true;
    }
    return false;
}

//--- clearCart ------------------------------------------------------------------------------------
// What    : Frees every node of the cart. Done at logout and at the end of the program.
// Used by : doCart (store.h), doCheckout (store.h), doLogin (store.h), doLogout (store.h), runStore
//           (store.h)
//--------------------------------------------------------------------------------------------------
void clearCart(Cart& cart) {
    CartNode* cur = cart.head;
    while (cur != nullptr) {
        CartNode* nxt = cur->next;
        delete cur;
        cur = nxt;
    }
    cart.head = nullptr;
    cart.count = 0;
}

#endif //STEAM_CART_H
